const fs=require('node:fs/promises');
const path=require('node:path');
const crypto=require('node:crypto');
const {Readable}=require('node:stream');
const {pipeline}=require('node:stream/promises');
const {createWriteStream}=require('node:fs');
const {validateResources,syncResources,verifyResources}=require('./resource-packs.cjs');
async function response(url){
 if(new URL(url).protocol!=='https:')throw Error('Las descargas deben usar HTTPS.');
 const r=await fetch(url,{signal:AbortSignal.timeout(180000),redirect:'follow'});
 if(!r.ok)throw Error(`No se pudo descargar el archivo (HTTP ${r.status}).`);
 if(new URL(r.url).protocol!=='https:')throw Error('Redireccion insegura.');
 return r;
}
async function jsonRemote(url){const r=await response(url);const t=await r.text();if(t.length>5e6)throw Error('Pack demasiado grande.');return JSON.parse(t);}
async function hash(file){const h=crypto.createHash('sha256');const f=await fs.open(file);try{for await(const b of f.createReadStream())h.update(b);}finally{await f.close().catch(()=>{});}return h.digest('hex');}
async function download(url,file,sha){
 const temp=file+'.download';await fs.mkdir(path.dirname(file),{recursive:true});
 try{const r=await response(url);await pipeline(Readable.fromWeb(r.body),createWriteStream(temp,{flags:'wx'}));
 if(sha&&(await hash(temp))!==sha.toLowerCase())throw Error('La descarga no coincide con su firma SHA256.');
 await fs.rename(temp,file);
 }finally{await fs.rm(temp,{force:true}).catch(()=>{});}
}
function validate(pack){
 if(pack.minecraft!=='1.20.1'||pack.forge!=='47.4.0'||!Array.isArray(pack.mods)||pack.mods.length>1000)throw Error('Pack incompatible o invalido.');
 const seen=new Set();
 for(const m of pack.mods){
 if(typeof m.file!=='string'||!/^[a-zA-Z0-9_()+. -]+\.jar$/.test(m.file)||m.file.length>180||/[. ]$/.test(m.file)||/^(con|prn|aux|nul|com[1-9]|lpt[1-9])\./i.test(m.file))throw Error('Nombre de mod invalido.');
 const key=m.file.toLowerCase();if(seen.has(key))throw Error('Mod duplicado.');seen.add(key);
 if(!/^[a-f0-9]{64}$/i.test(m.sha256)||new URL(m.url).protocol!=='https:')throw Error('Mod sin hash o HTTPS valido.');
 }
