}
function verifyEnvelope(envelope,publicKey){
 if(typeof envelope.payload!=='string'||typeof envelope.signature!=='string')throw Error('Falta la firma del administrador.');
 const data=Buffer.from(envelope.payload,'base64');
 if(!crypto.verify(null,data,publicKey,Buffer.from(envelope.signature,'base64')))throw Error('La firma del pack no pertenece a Blu.');
