 try{
 for(let i=0;i<pack.mods.length;i++){
  const m=pack.mods[i],dest=path.join(mods,m.file);status(`Verificando mods: ${i+1}/${pack.mods.length}`,i/Math.max(1,pack.mods.length));
  const st=await fs.lstat(dest).catch(e=>{if(e.code!=='ENOENT')throw e;return null;});
