 await fs.mkdir(backup,{recursive:true});
 for(const n of new Set([...changes,...extras.map(f=>f.name)])){
  try{await fs.rename(path.join(mods,n),path.join(backup,n));moved.push(n);}catch(e){if(e.code!=='ENOENT')throw e;}
 }
 for(const n of changes){await fs.rename(path.join(stage,n),path.join(mods,n));installed.push(n);}
