 }catch(e){
  for(const n of installed)await fs.rm(path.join(mods,n),{force:true});
  for(const n of moved)await fs.rename(path.join(backup,n),path.join(mods,n));
  throw e;
 }finally{await fs.rm(stage,{recursive:true,force:true});}
}
async function verifyMods(pack,instance){
 validate(pack);const mods=path.join(instance,'mods');
 for(const dir of [instance,mods]){const s=await fs.lstat(dir);if(!s.isDirectory()||s.isSymbolicLink())throw Error('La instancia o la carpeta mods fue sustituida por un enlace.');}
 const expected=new Map(pack.mods.map(m=>[m.file.toLowerCase(),m]));
 const entries=await fs.readdir(mods,{withFileTypes:true});
 if(entries.length!==pack.mods.length)throw Error('La carpeta de mods cambio: hay archivos extra o faltantes.');
 for(const f of entries){
  const approved=expected.get(f.name.toLowerCase());
  if(!approved||!f.isFile()||f.isSymbolicLink())throw Error('Se detecto un archivo no autorizado en mods.');
  if((await hash(path.join(mods,f.name)))!==approved.sha256.toLowerCase())throw Error('Se detecto un mod modificado: '+approved.file);
 }
 await verifyResources(pack,instance,hash);return true;
}
module.exports={jsonRemote,hash,download,validate,verifyEnvelope,verifyGithubManifest,syncPack,verifyMods};

