const fs=require('node:fs/promises');const path=require('node:path');const {spawn}=require('node:child_process');const extract=require('extract-zip');
const {jsonRemote,download}=require('./pack.cjs');
async function ensureJava(root,status){
 const target=path.join(root,'java17');const info=path.join(target,'runtime.json');
 try{const data=JSON.parse(await fs.readFile(info,'utf8'));const exe=path.join(target,data.home,'bin','java.exe');if(await version17(exe))return exe;}catch{}
 status('Descargando Java 17. Solo la primera vez...',0);
 const assets=await jsonRemote('https://api.adoptium.net/v3/assets/latest/17/hotspot?architecture=x64&image_type=jre&os=windows&vendor=eclipse');
 const pkg=assets?.[0]?.binary?.package;
 if(!pkg||!/^[a-f0-9]{64}$/i.test(pkg.checksum))throw Error('No se encontro Java 17 para Windows.');
 const stage=await fs.mkdtemp(path.join(root,'.java-'));const zip=path.join(stage,'runtime.zip');
 try{
 await download(pkg.link,zip,pkg.checksum);const dest=path.join(stage,'unpacked');await extract(zip,{dir:dest});
 const homes=await fs.readdir(dest);let home;
 for(const h of homes){if(await version17(path.join(dest,h,'bin','java.exe'))){home=h;break;}}
 if(!home)throw Error('Java descargado no es version 17.');
 await fs.writeFile(path.join(dest,'runtime.json'),JSON.stringify({home}));
