function version17(exe){return new Promise(resolve=>{let s='';const p=spawn(exe,['-version'],{windowsHide:true});p.stderr.on('data',b=>s+=b);p.once('error',()=>resolve(false));p.once('close',code=>resolve(code===0&&/version "17[.\"]/.test(s)));});}
module.exports={ensureJava};

