}
async function checkUpdate(url,key,current){
 const fresh=new URL(url);if(fresh.protocol!=='https:')throw Error('Usa HTTPS.');fresh.searchParams.set('_blu',String(Date.now()));
 const response=await fetch(fresh.href,{redirect:'follow',signal:AbortSignal.timeout(15000),headers:{'Cache-Control':'no-cache'}});
 if(!response.ok||new URL(response.url).protocol!=='https:')throw Error('No se pudo comprobar la actualización.');
