const fs=require('node:fs/promises');
const API='https://api.minecraftservices.com';
function skinPng(bytes){
 if(bytes.length<24||bytes.length>2e6||!bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))throw Error('Elige una skin PNG valida.');
 const width=bytes.readUInt32BE(16),height=bytes.readUInt32BE(20);
 if(width!==64||![32,64].includes(height))throw Error('La skin debe medir 64x64 o 64x32 pixeles.');
 return bytes;
}
async function accountRequest(token,endpoint,options={}){
 if(!token)throw Error('Inicia sesion con Microsoft para cambiar tu aspecto.');
 const r=await fetch(API+endpoint,{...options,redirect:'error',headers:{Authorization:'Bearer '+token,...options.headers},signal:AbortSignal.timeout(30000)});
 if(!r.ok){if(r.status===401||r.status===403)throw Error('Tu sesion no permite este cambio. Vuelve a iniciar sesion.');throw Error('Minecraft no pudo guardar el cambio (HTTP '+r.status+').');}
 if(r.status===204)return null;const text=await r.text();return text?JSON.parse(text):null;
}
function getProfile(token){return accountRequest(token,'/minecraft/profile');}
async function uploadSkin(token,file,variant){
 if(!['classic','slim'].includes(variant))throw Error('Modelo de skin invalido.');
 const stat=await fs.stat(file);if(stat.size>2e6)throw Error('La skin es demasiado grande.');
 const bytes=skinPng(await fs.readFile(file));
 const form=new FormData();form.append('variant',variant);form.append('file',new Blob([bytes],{type:'image/png'}),'skin.png');
