 const r=await fetch(u,{redirect:'error',signal:AbortSignal.timeout(12000)});if(!r.ok)return null;
 const b=Buffer.from(await r.arrayBuffer());if(b.length<24||b.length>2e6||!b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))return null;
