const fs=require('node:fs/promises'),path=require('node:path'),crypto=require('node:crypto');
const resourceGroups=['resourcepacks','shaderpacks'];
function validateResources(pack){
 for(const group of resourceGroups){
  const files=pack[group]??[];if(!Array.isArray(files)||files.length>200)throw Error('Lista de paquetes invalida.');const names=new Set();
  for(const file of files){
   if(typeof file.file!=='string'||!/^[a-zA-Z0-9_()+. -]+\.zip$/.test(file.file)||file.file.length>180||/^(con|prn|aux|nul|com[1-9]|lpt[1-9])\./i.test(file.file))throw Error('Nombre de paquete no permitido.');
   const name=file.file.toLowerCase();if(names.has(name))throw Error('Paquete duplicado.');names.add(name);
   if(!/^[a-f0-9]{64}$/i.test(file.sha256)||new URL(file.url).protocol!=='https:')throw Error('Paquete sin SHA256 o HTTPS valido.');
  }
 }
}
async function regularDirectory(dir){await fs.mkdir(dir,{recursive:true});const s=await fs.lstat(dir);if(!s.isDirectory()||s.isSymbolicLink())throw Error('No se permiten enlaces en las carpetas del pack.');}
async function syncResources(pack,instance,status,download,hash){
 validateResources(pack);
 for(const group of resourceGroups){
  const entries=pack[group]??[];const dir=path.join(instance,group);await regularDirectory(dir);
  const stage=await fs.mkdtemp(path.join(instance,'.'+group+'-sync-'));const changes=[],moved=[],installed=[];let backup;
  try{
   for(const item of entries){
    const dest=path.join(dir,item.file),st=await fs.lstat(dest).catch(e=>{if(e.code!=='ENOENT')throw e;return null;});
    if(st&&(!st.isFile()||st.isSymbolicLink()))throw Error('Un paquete autorizado fue sustituido por una carpeta o enlace.');
    if(st&&(await hash(dest))===item.sha256.toLowerCase())continue;
    status('Verificando paquetes del estudio...',null);const file=path.join(stage,item.file);await download(item.url,file,item.sha256);
    if((await hash(file))!==item.sha256.toLowerCase())throw Error('SHA256 de paquete incorrecto.');changes.push(item.file);
   }
   const wanted=new Set(entries.map(x=>x.file.toLowerCase()));const extras=(await fs.readdir(dir,{withFileTypes:true})).filter(x=>!wanted.has(x.name.toLowerCase()));
   for(const item of extras)if(item.isSymbolicLink())throw Error('No se permiten enlaces dentro de paquetes.');
   if(changes.length||extras.length){
    backup=path.join(instance,group+'-backup',crypto.randomUUID());await fs.mkdir(backup,{recursive:true});
    for(const name of new Set([...changes,...extras.map(x=>x.name)])){try{await fs.rename(path.join(dir,name),path.join(backup,name));moved.push(name);}catch(e){if(e.code!=='ENOENT')throw e;}}
    for(const name of changes){await fs.rename(path.join(stage,name),path.join(dir,name));installed.push(name);}
   }
  }catch(e){for(const name of installed)await fs.rm(path.join(dir,name),{force:true});for(const name of moved)await fs.rename(path.join(backup,name),path.join(dir,name));throw e;}
  finally{await fs.rm(stage,{recursive:true,force:true});}
 }
}
async function verifyResources(pack,instance,hash){
 validateResources(pack);
 for(const group of resourceGroups){
  const entries=pack[group]??[],dir=path.join(instance,group);const st=await fs.lstat(dir);
  if(!st.isDirectory()||st.isSymbolicLink())throw Error('La carpeta de paquetes fue sustituida.');
  const files=await fs.readdir(dir,{withFileTypes:true});if(files.length!==entries.length)throw Error('Se detectaron paquetes extra o faltantes.');
  const allowed=new Map(entries.map(x=>[x.file.toLowerCase(),x]));
  for(const file of files){const approved=allowed.get(file.name.toLowerCase());if(!approved||!file.isFile()||file.isSymbolicLink())throw Error('Se detecto un paquete no autorizado.');if((await hash(path.join(dir,file.name)))!==approved.sha256.toLowerCase())throw Error('Se detecto un paquete modificado: '+approved.file);}
 }
 return true;
}
module.exports={resourceGroups,validateResources,syncResources,verifyResources};

