const {gifData}=require('./image-assets.cjs');
const ADMIN_UUID='0a41fc2723ff46efaf5bda6933ba120d';
const defaults={studio:'BLUU CLIENT',pack:'KAZINO',tagline:'Tu próximo mundo empieza aquí.',announcement:'',playLabel:'JUGAR',server:'',accent:'#e7c681',background:'#0c1011',panel:'#121819',font:'segoe',radius:12,logoScale:64,darkness:35,compact:false,logo:null,banner:null,studioLogo:null,instanceIcon:null,layers:[{id:'client-logo',name:'Logo del cliente',image:'client',area:'banner',x:92,y:19,width:9,opacity:100,rotation:0}]};
function isOwner(profile){return typeof profile?.id==='string'&&profile.id.replace(/-/g,'').toLowerCase()===ADMIN_UUID;}
function normalizeTheme(input){
 if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Personalizacion invalida.');
 const out={...defaults};
 for(const [key,max] of [['studio',30],['pack',30],['tagline',100],['announcement',240],['playLabel',24],['server',120]]){
  if(input[key]!==undefined){if(typeof input[key]!=='string'||input[key].length>max||/[\x00-\x1f\x7f]/.test(input[key]))throw Error('Texto no valido: '+key);out[key]=input[key].trim();}
 }
 if(out.studio==='BLU STUDIO')out.studio='BLUU CLIENT';
 if(!out.studio||!out.pack||!out.playLabel)throw Error('El estudio, pack y boton necesitan un nombre.');
 if(out.server&&!/^[a-zA-Z0-9._:-]+$/.test(out.server))throw Error('Direccion de servidor invalida.');
 for(const key of ['accent','background','panel'])if(input[key]!==undefined){if(!/^#[a-f0-9]{6}$/i.test(input[key]))throw Error('Color invalido.');out[key]=input[key];}
 if(input.font!==undefined){if(!['segoe','trebuchet','mono'].includes(input.font))throw Error('Tipografia invalida.');out.font=input.font;}
 for(const [key,min,max] of [['radius',0,28],['logoScale',25,95],['darkness',0,85]])if(input[key]!==undefined){if(!Number.isInteger(input[key])||input[key]<min||input[key]>max)throw Error('Valor fuera de rango: '+key);out[key]=input[key];}
 if(input.compact!==undefined){if(typeof input.compact!=='boolean')throw Error('Densidad invalida.');out.compact=input.compact;}
 for(const key of ['logo','banner','studioLogo','instanceIcon'])if(input[key]!=null){if(typeof input[key]!=='string'||input[key].length>(input[key].startsWith('data:image/gif;')?11500000:2200000)||!/^data:image\/(png|jpeg|webp|gif);base64,[a-zA-Z0-9+/]+=*$/.test(input[key]))throw Error('Imagen no permitida. Usa PNG, JPG, WebP o GIF.');if(input[key].startsWith('data:image/gif;'))gifData(Buffer.from(input[key].split(',')[1],'base64'));out[key]=input[key];}
 if(input.layers!==undefined){
  if(!Array.isArray(input.layers)||input.layers.length>10)throw Error('Puedes poner hasta 10 imagenes.');
  const seen=new Set();out.layers=input.layers.map(layer=>{
   if(!layer||typeof layer!=='object'||!/^[a-zA-Z0-9_-]{1,60}$/.test(layer.id)||seen.has(layer.id))throw Error('Capa invalida o duplicada.');seen.add(layer.id);
   if(typeof layer.name!=='string'||!layer.name.trim()||layer.name.length>40)throw Error('Nombre de capa invalido.');
   if(!['banner','home','sidebar'].includes(layer.area))throw Error('Zona de imagen invalida.');
   if(layer.image!=='client'&&(typeof layer.image!=='string'||layer.image.length>(layer.image.startsWith('data:image/gif;')?11500000:2200000)||!/^data:image\/(png|jpeg|webp|gif);base64,[a-zA-Z0-9+/]+=*$/.test(layer.image)))throw Error('Imagen de capa invalida.');
   if(layer.image.startsWith('data:image/gif;'))gifData(Buffer.from(layer.image.split(',')[1],'base64'));
   const result={id:layer.id,name:layer.name.trim(),image:layer.image,area:layer.area};
   for(const [key,min,max] of [['x',0,100],['y',0,100],['width',2,100],['opacity',0,100],['rotation',-180,180]]){
    if(typeof layer[key]!=='number'||!Number.isFinite(layer[key])||layer[key]<min||layer[key]>max)throw Error('Posicion de capa invalida: '+key);result[key]=Math.round(layer[key]*10)/10;
   }
   return result;
  });
 }
 if(JSON.stringify(out).length>16000000)throw Error("Las imagenes juntas son demasiado grandes. Usa archivos mas ligeros.");
 return out;
}
module.exports={ADMIN_UUID,defaults,isOwner,normalizeTheme};

