`;
}
async function ensureDesktopShortcut({platform,packaged,executable,desktop,shell,fs,fallback,iconPath}){
 if(platform!=='win32'||!packaged)return 'skipped';
 if(typeof executable!=='string'||!path.win32.isAbsolute(executable)||path.win32.extname(executable).toLowerCase()!=='.exe')return 'skipped';
 const link=path.win32.join(desktop,'Bluu Client.lnk');
 const options={target:executable,cwd:path.win32.dirname(executable),description:'Abrir Bluu Client',icon:iconPath||executable,iconIndex:0,appUserModelId:ID};
 async function removeLegacy(){const old=path.win32.join(desktop,'Blu Studio.lnk');try{await fs.lstat(old);const info=shell.readShortcutLink(old);if(info.appUserModelId===ID||info.description==='Abrir Blu Studio Launcher')await fs.unlink(old);}catch{}}
 let exists=false;
 try{await fs.lstat(link);exists=true;}catch(e){if(e.code!=='ENOENT')throw e;}
 if(exists){
  let current;try{current=shell.readShortcutLink(link);}catch{return 'preserved';}
  if(current.appUserModelId!==ID&&!['Abrir Bluu Client','Abrir Blu Studio Launcher'].includes(current.description))return 'preserved';
  if(typeof current.target==='string'&&current.target.toLowerCase()===executable.toLowerCase()&&(!iconPath||current.icon?.toLowerCase()===iconPath.toLowerCase())){await removeLegacy();return 'exists';}
 }
 let written=false;try{written=shell.writeShortcutLink(link,exists?'update':'create',options);}catch{}
 if(!written&&fallback){await fallback(shortcutScript({link,target:executable,icon:iconPath||executable}));await fs.lstat(link);written=true;}
 if(!written)throw Error('Windows no permitio crear el acceso directo. Puedes reintentarlo desde Ajustes.');
 await removeLegacy();return exists?'updated':'created';
}
module.exports={ensureDesktopShortcut,shortcutScript};

