function playerFace(person){const canvas=document.createElement('canvas');canvas.width=canvas.height=48;canvas.className='playerFace';canvas.setAttribute('aria-label','Cara de '+(person.name||'jugador'));const ctx=canvas.getContext('2d');ctx.fillStyle='#263638';ctx.fillRect(0,0,48,48);ctx.fillStyle='#d5dacf';ctx.font='bold 20px Segoe UI';ctx.textAlign='center';ctx.fillText((person.name||'?')[0].toUpperCase(),24,31);const skin=playerSkinCache.get(person.uuid)?.skin||person.skin;if(skin){const img=new Image();img.onload=()=>{const scale=img.naturalWidth/64;if(!Number.isInteger(scale)||scale<1)return;ctx.clearRect(0,0,48,48);ctx.imageSmoothingEnabled=false;ctx.drawImage(img,8*scale,8*scale,8*scale,8*scale,0,0,48,48);ctx.drawImage(img,40*scale,8*scale,8*scale,8*scale,0,0,48,48);};img.src=skin;}return canvas;}
