const {isOwner}=require('./theme.cjs');
const defaults={schema:1,mode:'closed',message:'Kazino todavía no está disponible. El estudio avisará cuando puedas entrar.',opensAt:null,allowed:[]};
function normalizeAccess(input){
 if(!input||typeof input!=='object'||!['closed','invited','scheduled','open'].includes(input.mode)||typeof input.message!=='string'||input.message.length>600||/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(input.message)||!Array.isArray(input.allowed)||input.allowed.length>100)throw Error('Control de acceso inválido.');
 const allowed=[],seen=new Set();for(const entry of input.allowed){const uuid=typeof entry?.uuid==='string'?entry.uuid.replace(/-/g,'').toLowerCase():'';if(!/^[a-f0-9]{32}$/.test(uuid))throw Error('UUID de invitado inválido.');if(seen.has(uuid))continue;seen.add(uuid);allowed.push({uuid,name:typeof entry.name==='string'?entry.name.replace(/[^A-Za-z0-9_]/g,'').slice(0,16):''});}
 let opensAt=null;if(input.mode==='scheduled'){if(typeof input.opensAt!=='string'||!Number.isFinite(Date.parse(input.opensAt)))throw Error('Elige una fecha y hora válidas.');opensAt=new Date(input.opensAt).toISOString();}
 return {schema:1,mode:input.mode,message:input.message.trim()||defaults.message,opensAt,allowed};
}
function accessDecision(policy,profile,serverNow,{ownerBypass=true}={}){
 const p=normalizeAccess(policy);if(ownerBypass&&isOwner(profile))return {allowed:true,reason:'admin'};
 const uuid=typeof profile?.id==='string'?profile.id.replace(/-/g,'').toLowerCase():'';if(!/^[a-f0-9]{32}$/.test(uuid))return {allowed:false,reason:'identity',message:'Inicia sesión con tu cuenta de Minecraft.'};
 const invited=p.allowed.some(x=>x.uuid===uuid);const allowed=p.mode==='open'||(p.mode==='invited'&&invited)||(p.mode==='scheduled'&&(invited||(Number.isFinite(serverNow)&&serverNow>=Date.parse(p.opensAt))));
 return {allowed,reason:allowed?'allowed':p.mode,message:p.message,opensAt:p.opensAt};
}
async function fetchAccess(repository,fetcher=fetch){
 if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository))throw Error('Origen de acceso inválido.');
 const url='https://raw.githubusercontent.com/'+repository+'/main/launcher-access.json?t='+Date.now();const r=await fetcher(url,{redirect:'error',signal:AbortSignal.timeout(10000),headers:{'Cache-Control':'no-cache'}});if(!r.ok)throw Error('No se pudo comprobar el acceso. No se descargará el pack.');const text=await r.text();if(text.length>50000)throw Error('Control de acceso demasiado grande.');const policy=normalizeAccess(JSON.parse(text));return {policy,serverNow:Date.parse(r.headers.get('date'))};
}
async function withPackAccess({token,getProfile,loadPolicy,onDecision=()=>{},ownerBypass=true},run){
 const profile=await getProfile(token);let decision;if(ownerBypass&&isOwner(profile))decision={allowed:true,reason:'admin'};else{try{const {policy,serverNow}=await loadPolicy();decision=accessDecision(policy,profile,serverNow,{ownerBypass});}catch{decision={allowed:false,reason:'unavailable',message:'No se pudo verificar tu acceso. No se descargará el modpack. Intenta de nuevo más tarde.'};}}
 onDecision(decision,profile);if(!decision.allowed)throw Error(decision.message);return run(profile);
}
async function resolveAllowed(text,fetcher=fetch){
 if(typeof text!=='string'||text.length>10000)throw Error('Lista de invitados inválida.');const values=[...new Set(text.split(/[\s,;]+/).filter(Boolean))];if(values.length>100)throw Error('Máximo 100 invitados.');const entries=[];
 for(const value of values){const uuid=value.replace(/-/g,'').toLowerCase();if(/^[a-f0-9]{32}$/.test(uuid)){entries.push({uuid,name:''});continue;}if(!/^[A-Za-z0-9_]{3,16}$/.test(value))throw Error('Nombre inválido: '+value);const r=await fetcher('https://api.mojang.com/users/profiles/minecraft/'+encodeURIComponent(value),{redirect:'error',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('No se encontró la cuenta '+value+'. Revisa su nombre o introduce su UUID.');const account=await r.json();if(!/^[a-f0-9]{32}$/i.test(account.id)||typeof account.name!=='string')throw Error('No se pudo verificar '+value);entries.push({uuid:account.id.toLowerCase(),name:account.name});}
 return normalizeAccess({...defaults,allowed:entries}).allowed;
}
module.exports={defaults,normalizeAccess,accessDecision,fetchAccess,withPackAccess,resolveAllowed};

