const fs=require('node:fs/promises'),syncFs=require('node:fs'),path=require('node:path'),{spawn}=require('node:child_process');
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function cleanDiagnostic(value){return value.replace(/<[^>]*>/g,' ').replace(/_x000D_|_x000A_/g,' ').replace(/\s+/g,' ').trim().slice(-700);}
async function startWindowsUpdater({root,request,nonce,helperPath,env=process.env,spawnProcess=spawn,timeoutMs=45000}){
 const readyFile=path.join(root,'updater-ready.json'),logFile=path.join(root,'updater-startup.log');await fs.rm(readyFile,{force:true});
 const requestFile=path.join(root,'updater-request.json');await fs.writeFile(requestFile,JSON.stringify({...request,root,nonce}));
 const childEnv={...env};for(const name of ['ELECTRON_RUN_AS_NODE','NODE_OPTIONS','PORTABLE_EXECUTABLE_FILE','PORTABLE_EXECUTABLE_DIR','PORTABLE_EXECUTABLE_APP_FILENAME','PSModulePath'])delete childEnv[name];
 const fd=syncFs.openSync(logFile,'w');let updater,ended=false,exitCode=null,childError;
 try{
  updater=spawnProcess(helperPath,[requestFile],{windowsHide:true,detached:true,stdio:['ignore',fd,fd],cwd:root,env:childEnv});
  updater.on('error',error=>{childError=error;ended=true;});updater.on('exit',code=>{ended=true;exitCode=code;});
  await new Promise((resolve,reject)=>{updater.once('spawn',resolve);updater.once('error',reject);});
 }finally{syncFs.closeSync(fd);}
 const deadline=Date.now()+timeoutMs;
 while(Date.now()<deadline){
  try{const ready=JSON.parse((await fs.readFile(readyFile,'utf8')).replace(/^\uFEFF/,''));if(ready.nonce===nonce){updater.unref();return updater;}}catch{}
  if(ended)break;await delay(100);
 }
 if(!ended)updater.kill();
 const raw=await fs.readFile(logFile,'utf8').catch(()=>''),detail=cleanDiagnostic(raw);
 const reason=childError?.message||(ended?'El proceso terminó con código '+exitCode:'Windows tardó más de 45 segundos en iniciar el actualizador');
 const message=reason+(detail?'. '+detail:'. No se recibió la confirmación de arranque.')+' El launcher sigue abierto. El diagnóstico quedó guardado para revisarlo.';
 await fs.writeFile(path.join(root,'updater-last-error.txt'),message).catch(()=>{});throw Error(message);
}
module.exports={startWindowsUpdater,cleanDiagnostic};

