function gifData(bytes){
 if(!Buffer.isBuffer(bytes)||bytes.length<14||bytes.length>8000000||!['GIF87a','GIF89a'].includes(bytes.subarray(0,6).toString('ascii')))throw Error('GIF inválido o demasiado grande. Máximo 8 MB.');
 const w=bytes.readUInt16LE(6),h=bytes.readUInt16LE(8);if(!w||!h||w>2560||h>2560||w*h>4000000)throw Error('El GIF es demasiado grande. Usa hasta 2560 píxeles y 4 megapíxeles.');
 return 'data:image/gif;base64,'+bytes.toString('base64');
}
module.exports={gifData};

