const path=require('node:path'),fs=require('node:fs/promises');const {normalizeTheme}=require('./theme.cjs'),{normalizeAccess,defaults:accessDefaults}=require('./access.cjs'),{isOwner}=require('./theme.cjs');
const validId=id=>typeof id==='string'&&/^[a-z0-9][a-z0-9_-]{0,39}$/.test(id)&&!/^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/.test(id);
function normalizeCatalog(input){
 if(!input||input.schema!==1||!Array.isArray(input.instances)||input.instances.length>30)throw Error('Catálogo de instancias inválido. Máximo 30 instancias.');
 const ids=new Set(),instances=input.instances.map(item=>{if(!item||!validId(item.id)||ids.has(item.id))throw Error('ID de instancia inválido o duplicado.');ids.add(item.id);if(typeof item.name!=='string'||!item.name.trim()||item.name.length>30||/[\x00-\x1f\x7f]/.test(item.name)||typeof item.description!=='string'||item.description.length>240||!['public','owner','selected'].includes(item.visibility))throw Error('Datos de instancia inválidos.');
 const viewers=normalizeAccess({...accessDefaults,allowed:item.viewers||[]}).allowed;
 const result={id:item.id,name:item.name.trim(),description:item.description.trim(),visibility:item.visibility,viewers,theme:item.theme==null?null:normalizeTheme(item.theme),access:item.access==null?null:normalizeAccess(item.access)};return result;});
 const result={schema:1,instances};if(JSON.stringify(result).length>20000000)throw Error('Las imágenes del catálogo ocupan demasiado. Usa archivos más ligeros.');return result;
}
function canSee(instance,profile,admin=false){if(admin&&isOwner(profile))return true;if(instance.visibility==='public')return true;if(instance.visibility==='owner')return false;const id=typeof profile?.id==='string'?profile.id.replace(/-/g,'').toLowerCase():'';return instance.viewers.some(x=>x.uuid===id);}
function visibleInstances(catalog,profile,admin=false){return normalizeCatalog(catalog).instances.filter(i=>canSee(i,profile,admin));}
function instanceRoot(root,instance){if(!validId(instance?.id))throw Error('Instancia inválida.');return instance.id==='kazino'?path.join(root,'instance'):path.join(root,'instances',instance.id);}
function packPrefix(instance){if(!validId(instance?.id))throw Error('Instancia inválida.');return instance.id==='kazino'?'':'instances/'+instance.id;}
async function fetchCatalog(repository,fetcher=fetch){if(!/^[\w.-]+\/[\w.-]+$/.test(repository))throw Error('Origen de instancias inválido.');const r=await fetcher('https://raw.githubusercontent.com/'+repository+'/main/launcher-instances.json?t='+Date.now(),{redirect:'error',signal:AbortSignal.timeout(30000),headers:{'Cache-Control':'no-cache'}});if(!r.ok)throw Error('No se pudo consultar el catálogo de instancias.');const text=await r.text();if(text.length>21000000)throw Error('Catálogo demasiado grande.');return {catalog:normalizeCatalog(JSON.parse(text)),serverNow:Date.parse(r.headers.get('date'))};}
async function prepareInstanceRoot(root,instance){const target=instanceRoot(root,instance);const ensure=async dir=>{await fs.mkdir(dir,{recursive:true});const stat=await fs.lstat(dir);if(!stat.isDirectory()||stat.isSymbolicLink())throw Error('La carpeta de instancia no puede ser un enlace.');};if(instance.id!=='kazino')await ensure(path.join(root,'instances'));await ensure(target);return target;}
function instancePolicy(instance,legacy){if(!instance)return null;const policy=normalizeAccess(instance.access||(instance.id==='kazino'?legacy:accessDefaults));if(instance.id!=='kazino'&&policy.message===accessDefaults.message)policy.message=instance.name+' todavía no está disponible. El estudio avisará cuando puedas entrar.';return policy;}
module.exports={instancePolicy,prepareInstanceRoot,normalizeCatalog,canSee,visibleInstances,instanceRoot,packPrefix,fetchCatalog,validId};

