const UUID=/^[a-f0-9]{32}$/;const NAME=/^[A-Za-z0-9_]{3,16}$/;
async function lookupPlayer(query,fetcher=fetch){
 if(typeof query!=='string')throw Error('Escribe el nombre de Minecraft.');query=query.trim();let uuid=query.replace(/-/g,'').toLowerCase(),name='';
 const get=async url=>{const r=await fetcher(url,{redirect:'error',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('No se encontró esa cuenta de Minecraft Java.');return r;};
 if(!UUID.test(uuid)){if(!NAME.test(query))throw Error('Nombre de Minecraft inválido.');const p=await(await get('https://api.mojang.com/users/profiles/minecraft/'+encodeURIComponent(query))).json();uuid=String(p.id||'').toLowerCase();name=p.name;if(!UUID.test(uuid)||!NAME.test(name))throw Error('Respuesta de cuenta inválida.');}
 let profile;try{profile=await(await get('https://sessionserver.mojang.com/session/minecraft/profile/'+uuid)).json();if(String(profile.id).toLowerCase()!==uuid||!NAME.test(profile.name))throw Error('Identidad de cuenta inválida.');name=profile.name;}catch(e){if(!name)throw e;}
 let skin=null;try{const property=profile?.properties?.find(p=>p.name==='textures');if(property&&property.value.length<50000){const data=JSON.parse(Buffer.from(property.value,'base64').toString('utf8')),url=new URL(data.textures?.SKIN?.url);if(url.hostname!=='textures.minecraft.net'||url.username||url.password||url.port||url.search||url.hash||!['http:','https:'].includes(url.protocol))throw Error('Origen de skin inválido.');url.protocol='https:';const bytes=Buffer.from(await(await get(url.href)).arrayBuffer());if(bytes.length<24||bytes.length>2000000||!bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))throw Error('Skin inválida.');const w=bytes.readUInt32BE(16),h=bytes.readUInt32BE(20);if(![64,128,256,512,1024].includes(w)||(h!==w&&h!==w/2))throw Error('Dimensiones inválidas.');skin='data:image/png;base64,'+bytes.toString('base64');}}catch{}
 return {uuid,name,skin};
}
module.exports={lookupPlayer};
